-- Mark Grace card tracker: card data.
--
-- Use this INSTEAD of `php seed.php` when the importer account isn't
-- working, or when you have no shell access. Import through phpMyAdmin
-- (or: mysql -u ADMIN -p otbdesig_wp298 < cards-insert.sql).
--
-- Requires INSERT, so run it as an admin account. Re-running is safe: it
-- refreshes card details but never clears an `owned` flag you've set.

ON DUPLICATE KEY UPDATE
  year=VALUES(year), section=VALUES(section), card_num=VALUES(card_num),
  set_name=VALUES(set_name), image=VALUES(image), sort_order=VALUES(sort_order);
